import json
s = json.load(open('/practice/splits.json'))
sel = set(s['select'])
print('probe ids in select?', 'math/algebra/461' in sel, 'math/geometry/461' in sel)
orig = {}
for split in ['select','baseline']:
    try:
        for l in open(f'/practice/original/{split}.jsonl'):
            r = json.loads(l)
            orig[(r['qid'], r['sample'])] = r
    except FileNotFoundError:
        pass
try:
    for l in open('/practice/baseline/original.jsonl'):
        r = json.loads(l)
        orig.setdefault((r['qid'], r['sample']), r)
except FileNotFoundError:
    pass
for q in ['math/algebra/461','math/geometry/461']:
    for smp in [0,1]:
        r = orig.get((q,smp))
        if r:
            print(q, smp, 'orig correct', r['correct'], 'finish', r['finish'], 'tokens', r['tokens'])
        else:
            print(q, smp, 'no stored original')

